def _author_conflict(real, stored):
    """Do the payload's authors and the DB's disagree about WHO they are?

    Family names must line up in order. Given names are then checked for
    substitution — the check this module did not have on 2026-09-02, when
    REF-00976 stored HASEGAWA Toshiyuki over a payload that said HASEGAWA Naoji
    and printed CLEAN, because five surnames matched and nothing looked further.
    """
    if [_norm(f) for f, _ in real] != [_norm(f) for f, _ in stored]:
        return True
    return any(_given_conflict(gr, gs) for (_, gr), (_, gs) in zip(real, stored))


def _disp(family, given):
    return ", ".join(x for x in (family, given) if x) or "?"


def repeated_author_name(authors):
    """The first name a payload's author array lists twice, or None.

    A byline never repeats an author, so a repeat means the deposit filed something else
    (affiliations, as REF-01034's Crossref record does; derive it from the `author` array
    of its logged payload) as authors. One
    home for the test: db.py correct-source refuses to write from such a payload, and
    verify_authors reports the source as MALFORMED-PAYLOAD rather than as a cross.
    """
    seen = set()
    for a in authors or ():
        key = _norm((a.get("family") or a.get("name") or "")) + "|" + _norm(a.get("given") or "")
        if key.strip("|") and key in seen:
            return (a.get("family") or a.get("name") or "").strip()
        seen.add(key)
    return None


def decodable_body_artefacts(ref_id):
    """'session/artefact' for each held artefact of `ref_id` that carries a decodable BODY: a
    derived text (the manifest's `derived` flag, with no declared content type -- a derived
    image or JSON declares its own), or a fetched text/HTML page. A metadata record (JSON,
    XML) is not a body, and bytes that do not decode are not either. Read by db.py's
    `--verbatim-exempt` refusal: the exemption is for a source that holds no such body."""
    out = []
    for a in _artefact_index():
        if a.ref_id != ref_id:
            continue
        ct = (a.content_type or "").lower()
        if not (ct.startswith("text/") or (a.derived and not ct)):
            continue
        body, _enc = a.body()
        if body:
            out.append("%s/%s" % (a.dname, a.artefact))
    return out


def payload_page_range(ref_id):
    """The `page` string of a held Crossref-shaped payload for `ref_id`, or None.

    Reads the manifest lines carrying this ref_id and parses each as `--verify-authors`
    does (a work under `message` with a DOI). The deposit is the only machine-knowable
    statement that the document is paged; nothing here curates what a landing page looks
    like. Read by db.py `record-scan`: a text with no page markers cannot be a full reading
    of a document its own deposit gives a page range.
    """
    for a in _artefact_index():
        if a.ref_id != ref_id or a.derived:
            continue
        try:
            msg = json.loads(a.path.read_text(encoding="utf-8")).get("message")
        except Exception:                                # noqa: BLE001 -- not JSON: not a payload
            continue
        if isinstance(msg, dict) and msg.get("DOI") and str(msg.get("page") or "").strip():
            return str(msg["page"]).strip()
    return None


